#!/usr/bin/env bash
# -----------------------------------------------------------------------------
# tests/run.sh — the one entry point to build and run this workspace.
#
# GENERATED by micro-os-scaffold from scaffold.json. Tool paths come from
# tests/scripts/env.sh, which is generated from the same file.
#
#   ./run.sh                  build, then run the selected tests
#   ./run.sh build            configure and build only
#   ./run.sh test [name ...]  build, then run CTest
#   ./run.sh list             list the CTest cases (* = run by default)
#   ./run.sh all              build, then run every case, hardware included
#   ./run.sh clean            remove this configuration's build tree
#
# Options:
#   -c, --config NAME   configuration (default: 'aarch32-rpi-zero-2w-cmake-gcc-debug')
#   --no-build          do not build before running
#   --hwd               include the hardware (-hwd) cases
#   --hwd-only          run only the hardware (-hwd) cases
#   -R, --regex RE      ad-hoc CTest regular expression
#   -v, --verbose       verbose CTest output
#   -h, --help          this text
#
# A name is an application directory (mtp-example), a full CTest name
# (cortexm-weactf411-mtp-example-hwd), or a selection id (as recorded in
# scaffold.json).
#
# Results are files too:
#   build/<configuration>/ctest.xml        the CTest JUnit summary (CTest keeps
#                                          only a 1 KiB console snippet per test)
#   build/<configuration>/ctest.log        the full CTest output, copied from
#                                          Testing/Temporary/LastTest.log
#   .hw-logs/<app>.tap                     the complete µTest++ TAP report,
#   .qemu-logs/<app>.tap                   next to the runner's own log
#   .host-logs/<app>.tap                   (QEMU / host)
# -----------------------------------------------------------------------------
set -uo pipefail
HERE="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
source "$HERE/scripts/env.sh"

DEFAULT_CONFIG='aarch32-rpi-zero-2w-cmake-gcc-debug'
CONFIGS=('aarch32-rpi-zero-2w-cmake-gcc-debug')
CMD=""
CONFIG=""
NO_BUILD=0
HWD=0
VERBOSE=0
REGEX=""
WANTED=()

usage() {
  sed -n '2,30p' "$0"
  exit 0
}

while [[ $# -gt 0 ]]; do
  case "$1" in
    -h|--help) usage ;;
    -c|--config)
      [[ $# -ge 2 ]] || { echo "--config needs a value" >&2; exit 2; }
      CONFIG="$2"
      shift
      ;;
    --no-build) NO_BUILD=1 ;;
    --hwd) HWD=1 ;;
    --hwd-only) HWD=2 ;;
    --all) CMD="all" ;;
    --list) CMD="list" ;;
    --clean) CMD="clean" ;;
    -v|--verbose) VERBOSE=1 ;;
    -R|--regex)
      [[ $# -ge 2 ]] || { echo "--regex needs a value" >&2; exit 2; }
      REGEX="$2"
      shift
      ;;
    build|test|list|clean|all) CMD="$1" ;;
    -*) echo "Unknown option: $1 (try --help)" >&2; exit 2 ;;
    *) WANTED+=("$1") ;;
  esac
  shift
done

CMD="${CMD:-test}"
CONFIG="${CONFIG:-$DEFAULT_CONFIG}"

PLATFORM=""
BUILD_TYPE="Debug"
TOOLCHAIN=""
HOST_COMPILERS=0
SELECTED=()
case "$CONFIG" in
  'aarch32-rpi-zero-2w-cmake-gcc-debug')
    PLATFORM='aarch32-rpi-zero-2w'
    BUILD_TYPE='Debug'
    TOOLCHAIN='xpacks/@micro-os-plus/build-helper/cmake/toolchains/arm-none-eabi-gcc.cmake'
    HOST_COMPILERS=
    SELECTED=('aarch32-rpi-zero-2w-smp-mat-test-qemu' 'aarch32-rpi-zero-2w-smp-mat-test-hwd' 'aarch32-rpi-zero-2w-mtp-example-qemu' 'aarch32-rpi-zero-2w-mtp-example-hwd' 'aarch32-rpi-zero-2w-mtp-args-qemu' 'aarch32-rpi-zero-2w-mtp-args-hwd' 'aarch32-rpi-zero-2w-mtp-smp-qemu' 'aarch32-rpi-zero-2w-mtp-smp-hwd' 'aarch32-rpi-zero-2w-mtp-stdcpp-qemu' 'aarch32-rpi-zero-2w-mtp-stdcpp-hwd')
    ;;
  *)
    echo "Unknown configuration: $CONFIG" >&2
    echo "Known: ${CONFIGS[*]}" >&2
    exit 2
    ;;
esac

BUILD_DIR="$HERE/build/$CONFIG"

configure_and_build() {
  # A build tree copied or moved from another workspace keeps absolute paths
  # in its CMake cache. Detect that and start clean, instead of letting CMake
  # fail with "current CMakeCache.txt directory is different". This is what
  # makes a renamed workspace build after a move.
  if [[ -f "$BUILD_DIR/CMakeCache.txt" ]]; then
    local cached_dir cached_src
    cached_dir="$(sed -n 's/^CMAKE_CACHEFILE_DIR:INTERNAL=//p' "$BUILD_DIR/CMakeCache.txt" | head -n 1)"
    cached_src="$(sed -n 's/^CMAKE_HOME_DIRECTORY:INTERNAL=//p' "$BUILD_DIR/CMakeCache.txt" | head -n 1)"
    if [[ "$cached_dir" != "$BUILD_DIR" || "$cached_src" != "$HERE" ]]; then
      echo "== build tree was moved from ${cached_dir:-another folder}; reconfiguring"
      rm -rf "$BUILD_DIR"
    fi
  fi

  mkdir -p "$BUILD_DIR/xpacks/@xpacks" "$BUILD_DIR/xpacks/@xpack-3rd-party"
  for pair in \
    "UOS_LIB_LIBUCONTEXT:$BUILD_DIR/xpacks/@xpack-3rd-party/libucontext" \
    "UOS_LIB_ARM_CMSIS_CORE:$BUILD_DIR/xpacks/@xpack-3rd-party/arm-cmsis-core" \
    "UOS_LIB_ARM_CMSIS:$BUILD_DIR/xpacks/@xpacks/arm-cmsis" \
    "UOS_LIB_RASPBERRYPI_PICO_SDK:$BUILD_DIR/xpacks/@xpack-3rd-party/raspberrypi-pico-sdk"; do
    local var="${pair%%:*}" target="${pair#*:}" source_path
    source_path="${!var:-}"
    if [[ -n "$source_path" && -d "$source_path" ]]; then
      ln -sfn "$source_path" "$target"
    fi
  done

  local args=(-S "$HERE" -B "$BUILD_DIR" -G Ninja
              -D "CMAKE_BUILD_TYPE=$BUILD_TYPE" -D "PLATFORM_NAME=$PLATFORM")
  [[ -n "$TOOLCHAIN" ]] && args+=(-D "CMAKE_TOOLCHAIN_FILE=$HERE/$TOOLCHAIN")
  if [[ "$HOST_COMPILERS" == "1" ]]; then
    [[ -n "${UOS_TOOL_GCC:-}" ]] && args+=(-D "CMAKE_C_COMPILER=$UOS_TOOL_GCC")
    [[ -n "${UOS_TOOL_G__:-}" ]] && args+=(-D "CMAKE_CXX_COMPILER=$UOS_TOOL_G__")
  fi
  # Extra CMake options, e.g. UOS_CMAKE_ARGS='-DFOO=1' ./run.sh build
  if [[ -n "${UOS_CMAKE_ARGS:-}" ]]; then
    eval "_extra=(${UOS_CMAKE_ARGS})"
    args+=("${_extra[@]}")
  fi

  echo "== configure $CONFIG (platform=$PLATFORM, build=$BUILD_TYPE)"
  cmake "${args[@]}" || exit $?
  echo "== build $CONFIG"
  cmake --build "$BUILD_DIR" -- -k 0 || exit $?
}

registered() {
  ctest --test-dir "$BUILD_DIR" -N \
    | sed -n 's/^ *Test *#[0-9]*: *\([^ ]*\).*/\1/p'
}

# A selection id, as recorded in scaffold.json.
selection_names() {
  case "$CONFIG:$1" in
    'aarch32-rpi-zero-2w-cmake-gcc-debug:2.2.12') printf '%s\n' 'aarch32-rpi-zero-2w-smp-mat-test-qemu' 'aarch32-rpi-zero-2w-smp-mat-test-hwd' ;;
    *) ;;
  esac
}

# An application directory name, or an exact CTest name.
application_names() {
  local wanted="$1" name
  if grep -qx -- "$wanted" <<< "$REGISTERED"; then
    echo "$wanted"
    return
  fi
  while IFS= read -r name; do
    case "$name" in
      *"-$wanted-qemu"|*"-$wanted-hwd"|*"-$wanted-host"|*"-$wanted") echo "$name" ;;
    esac
  done <<< "$REGISTERED"
}

if [[ "$CMD" == "clean" ]]; then
  rm -rf "$BUILD_DIR"
  echo "Removed $BUILD_DIR"
  exit 0
fi

if [[ "$NO_BUILD" == "0" ]]; then
  configure_and_build
fi
[[ -d "$BUILD_DIR" ]] || {
  echo "No build tree: $BUILD_DIR (run ./run.sh build)" >&2
  exit 2
}

REGISTERED="$(registered)"

if [[ "$CMD" == "build" ]]; then
  exit 0
fi

if [[ "$CMD" == "list" ]]; then
  echo "CTest cases of $CONFIG (* = run by default):"
  while IFS= read -r name; do
    [[ -n "$name" ]] || continue
    mark=" "
    for selected in "${SELECTED[@]}"; do
      [[ "$name" == "$selected" ]] && mark="*"
    done
    echo "  $mark $name"
  done <<< "$REGISTERED"
  echo
  echo "When tests run:"
  echo "  $BUILD_DIR/ctest.xml   JUnit summary (console snippets capped by CTest)"
  echo "  $BUILD_DIR/ctest.log   full CTest output"
  echo "  .hw-logs|.qemu-logs|.host-logs/<app>.tap   complete µTest++ report"
  exit 0
fi

# ---------------------------------------------------------------------------
# Which cases.
NAMES=()
if [[ ${#WANTED[@]} -gt 0 ]]; then
  for wanted in "${WANTED[@]}"; do
    found="$(selection_names "$wanted")"
    [[ -n "$found" ]] || found="$(application_names "$wanted")"
    if [[ -z "$found" ]]; then
      echo "No test '$wanted' in $CONFIG." >&2
      echo "Try: ./run.sh list" >&2
      exit 2
    fi
    while IFS= read -r name; do
      [[ -n "$name" ]] && NAMES+=("$name")
    done <<< "$found"
  done
elif [[ "$CMD" == "all" || "$HWD" == "1" ]]; then
  while IFS= read -r name; do
    [[ -n "$name" ]] && NAMES+=("$name")
  done <<< "$REGISTERED"
else
  NAMES=("${SELECTED[@]}")
  [[ ${#NAMES[@]} -gt 0 ]] || {
    echo "No selected tests for $CONFIG: use --all, or name a test." >&2
    exit 2
  }
fi

# Hardware cases need the board and the probe: skip them unless asked for,
# except when there is nothing else to run.
if [[ "$HWD" == "2" ]]; then
  RUN=()
  for name in "${NAMES[@]}"; do
    [[ "$name" == *-hwd ]] && RUN+=("$name")
  done
  if [[ ${#RUN[@]} -eq 0 ]]; then
    echo "No hardware (-hwd) case among: ${NAMES[*]}" >&2
    exit 2
  fi
  NAMES=("${RUN[@]}")
elif [[ "$HWD" == "0" && "$CMD" != "all" ]]; then
  RUN=()
  for name in "${NAMES[@]}"; do
    [[ "$name" == *-hwd ]] || RUN+=("$name")
  done
  if [[ ${#RUN[@]} -eq 0 ]]; then
    RUN=("${NAMES[@]}")
    echo "Only hardware (-hwd) cases match: the board and the probe must be connected."
  fi
  NAMES=("${RUN[@]}")
fi

if [[ -n "$REGEX" ]]; then
  PATTERN="$REGEX"
else
  PATTERN=""
  for name in "${NAMES[@]}"; do
    escaped="$(sed 's/[][\.^$*+?(){}|]/\\&/g' <<< "$name")"
    PATTERN="${PATTERN:+$PATTERN|}$escaped"
  done
  PATTERN="^(${PATTERN})$"
fi

JUNIT=()
if ctest --help 2>&1 | grep -- '--output-junit' > /dev/null; then
  JUNIT=(--output-junit "$BUILD_DIR/ctest.xml")
fi
ARGS=(--test-dir "$BUILD_DIR" --output-on-failure "${JUNIT[@]}" -R "$PATTERN")
[[ "$VERBOSE" == "1" ]] && ARGS+=(-V)

echo "== run ${#NAMES[@]} case(s) of $CONFIG"
[[ ${#JUNIT[@]} -gt 0 ]] && echo "   JUnit: $BUILD_DIR/ctest.xml"
ctest "${ARGS[@]}"
status=$?

# CTest writes the full output of the run to a temporary log and the JUnit
# file only keeps a 1 KiB snippet of each test (CTest says so in the XML).
# Copy the full log under a stable name, next to ctest.xml.
if [[ -f "$BUILD_DIR/Testing/Temporary/LastTest.log" ]]; then
  cp "$BUILD_DIR/Testing/Temporary/LastTest.log" "$BUILD_DIR/ctest.log"
  echo "   Full CTest log: $BUILD_DIR/ctest.log"
fi
exit "$status"
